// Intended function: keep diplomacy symmetric and inspectable while emitting incidents for Chronicle/contract/AI consumers.
#include "strategy/DiplomacySystem.hpp"
#include "core/Determinism.hpp"
#include <algorithm>
namespace elysium{std::uint64_t DiplomacySystem::key(std::uint64_t a,std::uint64_t b){if(a>b)std::swap(a,b);return mix64(a^mix64(b));}void DiplomacySystem::setStanding(std::uint64_t a,std::uint64_t b,float v){if(a==b||!a||!b)return;if(a>b)std::swap(a,b);auto&r=relations_[key(a,b)];r.factionA=a;r.factionB=b;r.standing=std::clamp(v,-100.f,100.f);}void DiplomacySystem::addTreaty(std::uint64_t a,std::uint64_t b,TreatyKind t){setStanding(a,b,relation(a,b).value_or(DiplomaticRelation{}).standing);auto&r=relations_[key(a,b)];if(std::find(r.treaties.begin(),r.treaties.end(),t)==r.treaties.end())r.treaties.push_back(t);}void DiplomacySystem::removeTreaty(std::uint64_t a,std::uint64_t b,TreatyKind t){auto i=relations_.find(key(a,b));if(i!=relations_.end())i->second.treaties.erase(std::remove(i->second.treaties.begin(),i->second.treaties.end(),t),i->second.treaties.end());}void DiplomacySystem::applyIncident(DiplomaticIncident x){auto r=relation(x.actorFaction,x.targetFaction).value_or(DiplomaticRelation{x.actorFaction,x.targetFaction});setStanding(x.actorFaction,x.targetFaction,r.standing+x.standingDelta);relations_[key(x.actorFaction,x.targetFaction)].lastIncidentTick=x.tick;incidents_.push_back(x);}std::optional<DiplomaticRelation>DiplomacySystem::relation(std::uint64_t a,std::uint64_t b)const{auto i=relations_.find(key(a,b));return i==relations_.end()?std::nullopt:std::optional<DiplomaticRelation>(i->second);}std::vector<DiplomaticIncident>DiplomacySystem::drainIncidents(){auto o=std::move(incidents_);incidents_.clear();return o;}}
